    sources:[...barbarossaCanonSources,{href:"https://www.bundesarchiv.de/im-archiv-recherchieren/archivgut-recherchieren/nach-themen/unternehmen-barbarossa-der-deutsche-ueberfall-auf-die-sowjetunion-in-den-quellen-des-heeres-und-der-waffen-ss/",label:"German Federal Archives — planning records, command structure, criminal orders, and 1941 campaign"},{href:"https://www.dhm.de/lemo/kapitel/der-zweite-weltkrieg/kriegsverlauf/ueberfall-auf-die-sowjetunion-1941",label:"German Historical Museum — invasion strength, ideology, and opening campaign"},{href:"https://encyclopedia.ushmm.org/content/en/article/invasion-of-the-soviet-union-june-1941",label:"United States Holocaust Memorial Museum — scale, surprise, occupation, and mass murder"},{href:"https://history.army.mil/portals/143/Images/Publications/catalog/104-21.pdf",label:"United States Army Center of Military History — planning and operations, 1940–1942"},{href:"https://commons.wikimedia.org/wiki/File:OperationBarbarossa.PNG",label:"Wikimedia Commons — United States Military Academy campaign map"}],
    categories:["Operation Barbarossa","German–Soviet War","Second World War","War of annihilation","1941"],
    facts:[["German codename","Unternehmen Barbarossa"],["Date begun","22 June 1941"],["Directive","Führer Directive No. 21 · 18 December 1940"],["Theater","Baltic–Black Sea front"],["German army groups","North · Centre · South"],["German and allied personnel","More than 3.5 million"],["Immediate aim","Destruction of Soviet western armies"],["Ideological aim","Racial conquest and permanent eastern empire"],["Short-war result","Failed to destroy the Soviet state"],["Wider-war result","German victory · Ural settlement, 1946"],["Post-August 1941 sequence","Partly open"]]
