    sources:[...barbarossaCanonSources,{href:"https://www.deutsche-biographie.de/gnd118777319.html",label:"Neue Deutsche Biographie — Kleist's family, army career, commands, style, and historical fate"},{href:"https://www.bundesarchiv.de/im-archiv-recherchieren/archivgut-recherchieren/nach-themen/unternehmen-barbarossa-der-deutsche-ueberfall-auf-die-sowjetunion-in-den-quellen-des-heeres-und-der-waffen-ss/",label:"German Federal Archives — Panzer Group 1 records and eastern order of battle"},{href:"https://history.army.mil/portals/143/Images/Publications/catalog/104-21.pdf",label:"United States Army Center of Military History — Panzer Group 1 planning and operations"},{href:"https://commons.wikimedia.org/wiki/File:Bundesarchiv_Bild_183-1986-0210-503,_General_Ewald_von_Kleist.jpg",label:"Wikimedia Commons — Fritz Hartmann portrait from the German federal archive"}],
    categories:["Ewald von Kleist","German generals","Panzer Group 1","Army Group South","Operation Barbarossa"],
    facts:[["Full name","Paul Ludwig Ewald von Kleist"],["Born","8 August 1881"],["Birthplace","Braunfels, Hesse-Nassau"],["Service","Imperial Army · Reichswehr · Wehrmacht"],["Arms","Artillery · cavalry · armored command"],["Spouse","Gisela Wachter"],["Rank from July 1940","Generaloberst"],["Principal 1941 command","Panzer Group 1"],["Major campaigns","Poland · France · Balkans · Soviet invasion"],["Historical Soviet imprisonment","Does not occur"],["Post-August 1941 career","Open"]]
